<span class="line"><span style="color:#0077B3;">cd</span><span style="color:#101820;"> goravel</span><span style="color:#68747D;"> &amp;&amp;</span><span style="color:#0077B3;"> go</span><span style="color:#101820;"> mod</span><span style="color:#101820;"> tidy</span></span>
